namespace ghidra.app.plugin.core.decompile.actions;

using docking.action;
using ghidra.app.decompiler.component;
using ghidra.app.decompiler.component;
using ghidra.app.plugin.core.decompile;
using ghidra.app.util;
using ghidra.program.model.listing;
using ghidra.util;

/**
 * Removes all secondary highlights for the current function
 * 
 * @see ClangHighlightController
 */
public class RemoveAllSecondaryHighlightsAction : AbstractDecompilerAction {

	public static readonly string NAME = "Remove All Secondary Highlights";

	public RemoveAllSecondaryHighlightsAction() : base(NAME)
    {

		setPopupMenuData(new MenuData(
			new string[] { "Secondary Highlight", "Remove All Highlights" }, "Decompile"));
		setHelpLocation(new HelpLocation(HelpTopics.DECOMPILER, "ActionSecondaryHighlight"));
	}

	/* @Override */
	protected bool isEnabledForDecompilerContext(DecompilerActionContext context) {
		if (!context.hasRealFunction()) {
			return false;
		}

		DecompilerPanel panel = context.getDecompilerPanel();
		Function function = context.getFunction();
		return panel.hasSecondaryHighlights(function);
	}

	/* @Override */
	protected void decompilerActionPerformed(DecompilerActionContext context) {
		DecompilerPanel panel = context.getDecompilerPanel();
		Function function = context.getFunction();
		panel.removeSecondaryHighlights(function);
	}
}
